"""Writes the declarations of a built @polyjose/node package for scripts/tests/check-binding-api/node.sh.

Usage: python3 -I declarations.py <api-inventory.txt> <codes file> <package dir>

The node mode of scripts/check-binding-api.sh (feature 0007 T03; ADR 0030 §2, §4, §5; ADR 0031 §2)
reads the git-ignored output of bindings/node/scripts/build.sh. Its negative test must not depend on
whatever build the checkout happens to hold (0007 B02; pipeline rule 9), so this writes the files the
mode reads, derived at test time from the inventory and the core's Error::CODES (one per line, in
order, from lib.sh's core_codes), in the layout the build writes:
  - binding.d.ts, as `napi build --dts` writes it: the napi-rs header, the `__napiBindingTarget`
    loader const, and every operation (`export declare function <name>(`) and record
    (`export interface <Name> {`, two-space-indented members, `name?:` optional) sorted by name
    without regard to case, each with a doc comment, and doc comments inside the records. napi-rs
    writes a flag (inventory `= false`, Rust Option<bool>) as `name?: boolean`;
  - index.d.ts, as tsc writes src/index.ts: one `export declare const` list of the operations (in
    inventory order, with parameter lists whose commas, parentheses, generics, `=>` and import()
    strings the mode must split around) and PolyjoseError, then the ERROR_CODES re-export and
    `export type * from "./facade/api.js";`;
  - facade/error-codes.d.ts: the ERROR_CODES tuple in the core's order (ADR 0030 §5);
  - facade/api.d.ts: present only, as the mode requires it (its names are the js mode's).
Names come only from the inputs, so the fixture grows with the API and cannot drift from it; that
the real build still has this layout is checked by bindings/node/test.sh, which runs the mode on the
package it has just built (0007 B01).
"""

import os
import sys


def die(message):
    sys.exit("declarations.py: " + message)


def read_inventory(path):
    """The inventory's ops (in order) and records, each a (name, [(field, kind)]) pair, where kind
    is "required", "optional" or "flag" (the format in the inventory's header)."""
    ops, records = [], []
    with open(path, encoding="utf-8") as f:
        for number, raw in enumerate(f, 1):
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            words = line.split()
            kind, rest = words[0], " ".join(words[1:])
            if kind == "op":
                ops.append(rest)
            elif kind == "record":
                records.append((rest, []))
            elif kind == "field":
                if not records:
                    die("%s:%d: a field before any record" % (path, number))
                if rest.replace(" ", "").endswith("=false"):
                    records[-1][1].append((rest.split("=")[0].strip(), "flag"))
                elif rest.endswith("?"):
                    records[-1][1].append((rest[:-1], "optional"))
                else:
                    records[-1][1].append((rest, "required"))
            elif kind != "code":
                die("%s:%d: unknown entry %r" % (path, number, kind))
    if not ops or not records:
        die("%s: no operations or no records" % path)
    return ops, records


def binding_dts(ops, records):
    items = [(name.lower(), "op", name, None) for name in ops]
    items += [(name.lower(), "record", name, fields) for name, fields in records]
    out = [
        "/* auto-generated by NAPI-RS */",
        "/* eslint-disable */",
        "",
        "/**",
        " * Which binding artifact the generated loader actually loaded (test fixture of",
        " * scripts/tests/check-binding-api/node.sh).",
        " */",
        "export declare const __napiBindingTarget: 'native' | 'wasm32-wasi' | 'wasm32-wasip1'",
    ]
    for _, kind, name, fields in sorted(items):
        out.append("")
        if kind == "op":
            out.append("/** The %s operation (ADR 0030 §4). */" % name)
            out.append("export declare function %s(input: string, options: Options): Promise<unknown>" % name)
            continue
        out.append("/**")
        out.append(" * The %s record (ADR 0030 §4)." % name)
        out.append(" */")
        out.append("export interface %s {" % name)
        for i, (field, fkind) in enumerate(fields):
            if i % 2 == 0:
                out.append("  /** The %s field. */" % field)
            else:
                out.append("  /**")
                out.append("   * The %s field, documented over two lines." % field)
                out.append("   */")
            if fkind == "required":
                out.append("  %s: string" % field)
            elif fkind == "optional":
                out.append("  %s?: Array<string>" % field)
            else:
                out.append("  %s?: boolean" % field)
        out.append("}")
    return "\n".join(out) + "\n"


def index_dts(ops):
    types = 'import("./facade/types.js")'
    decls = ["%s: (input: %s.Jwk, options?: %s.Options) => Promise<%s.Result<string, number>>"
             % (name, types, types, types) for name in ops]
    decls.append('PolyjoseError: typeof import("./facade/api.js").PolyjoseError')
    return "\n".join([
        "/**",
        " * `@polyjose/node` (test fixture of scripts/tests/check-binding-api/node.sh).",
        " */",
        "export declare const " + ", ".join(decls) + ";",
        'export { ERROR_CODES } from "./facade/api.js";',
        'export type * from "./facade/api.js";',
        "//# sourceMappingURL=index.d.ts.map",
    ])


def error_codes_dts(codes):
    return "\n".join([
        "/** The stable error codes of every polyjose binding, in the core's order (ADR 0030 §5). */",
        "export declare const ERROR_CODES: readonly [" + ", ".join('"%s"' % c for c in codes) + "];",
        "/** One stable error code (ADR 0030 §5). */",
        "export type ErrorCode = (typeof ERROR_CODES)[number];",
        "//# sourceMappingURL=error-codes.d.ts.map",
    ])


API_DTS = "\n".join([
    "/** The shared facade (test fixture of scripts/tests/check-binding-api/node.sh). */",
    "export declare class PolyjoseError extends Error {",
    "    readonly code: string;",
    "}",
    'export { ERROR_CODES } from "./error-codes.js";',
    'export type * from "./types.js";',
    "//# sourceMappingURL=api.d.ts.map",
])


def write(path, text):
    with open(path, "w", encoding="utf-8") as f:
        f.write(text)


def main():
    if len(sys.argv) != 4:
        die("usage: declarations.py <api-inventory.txt> <codes file> <package dir>")
    inventory, codes_file, pkg = sys.argv[1:]
    ops, records = read_inventory(inventory)
    with open(codes_file, encoding="utf-8") as f:
        codes = [line.strip() for line in f if line.strip()]
    if not codes:
        die("%s has no codes" % codes_file)
    os.makedirs(os.path.join(pkg, "facade"), exist_ok=True)
    write(os.path.join(pkg, "binding.d.ts"), binding_dts(ops, records))
    write(os.path.join(pkg, "facade", "api.d.ts"), API_DTS)
    write(os.path.join(pkg, "facade", "error-codes.d.ts"), error_codes_dts(codes))
    write(os.path.join(pkg, "index.d.ts"), index_dts(ops))


main()
